#!/usr/bin/env bash
# Fan agents/, commands/ and the OpenCode plugins out into ~/.config/opencode.
#
#   commands/*.md          symlinked as-is — OpenCode ignores Claude Code's
#                          allowed-tools/argument-hint and supports $ARGUMENTS.
#   agents/*.md            GENERATED, not symlinked: Claude Code's `tools:` is a
#                          comma string, OpenCode rejects it and then refuses to
#                          load the whole config. Generated files get
#                          `mode: subagent` plus permissions mapped from `tools:`.
#   opencode/plugins/*.ts  symlinked into ~/.config/opencode/plugins/.
#
# Re-run after adding or editing an agent. Skills need nothing: OpenCode reads
# ~/.claude/skills natively.

set -euo pipefail

REPO="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
OC="$HOME/.config/opencode"
MARKER="Generated by agents-hub/opencode/sync-opencode.sh"

mkdir -p "$OC/agents" "$OC/commands" "$OC/plugins"

# Drop previously generated agents so a deleted source doesn't linger.
{ grep -l "$MARKER" "$OC/agents/"*.md 2>/dev/null || true; } | xargs rm -f

for src in "$REPO"/agents/*.md; do
  name=$(basename "$src" .md)
  frontmatter=$(awk 'NR==1 && /^---$/ {in_fm=1; next} in_fm && /^---$/ {exit} in_fm' "$src")
  description=$(echo "$frontmatter" | grep -m1 '^description:' || true)
  tools=$(echo "$frontmatter" | sed -n 's/^tools:[[:space:]]*//p')

  permission=""
  if [ -n "$tools" ]; then
    echo "$tools" | grep -qwE 'Edit|Write' || permission+=$'\n  edit: deny'
    echo "$tools" | grep -qw 'Bash' || permission+=$'\n  bash: deny'
  fi

  {
    echo "---"
    echo "$description"
    echo "mode: subagent"
    [ -n "$permission" ] && echo "permission:$permission"
    echo "---"
    echo
    echo "<!-- $MARKER from agents/$name.md. Edit the source, then re-run the script. -->"
    awk 'NR==1 && /^---$/ {in_fm=1; next} in_fm && /^---$/ {in_fm=0; next} !in_fm' "$src"
  } > "$OC/agents/$name.md"
  echo "agent    $name"
done

for src in "$REPO"/commands/*.md; do
  ln -sfn "$src" "$OC/commands/$(basename "$src")"
  echo "command  $(basename "$src" .md)"
done

for src in "$REPO"/opencode/plugins/*.ts; do
  ln -sfn "$src" "$OC/plugins/$(basename "$src")"
  echo "plugin   $(basename "$src" .ts)"
done
